<script setup>
import { computed, ref } from 'vue'
import { Plus, Search, Pencil, UsersRound, ArrowUpRight, Wallet, Copy, Link2 } from 'lucide-vue-next'
import { useAppStore } from '../stores/app'
import { api } from '../api'
import { money, initials } from '../utils/format'
import BaseModal from '../components/BaseModal.vue'
import PaymentTable from '../components/PaymentTable.vue'
import GoalProgress from '../components/GoalProgress.vue'
const store = useAppStore(), search = ref(''), filter = ref('all'), editing = ref(null), selected = ref(null), busy = ref(false), error = ref(''), access = ref(null), accessError = ref('')
const list = computed(()=>store.employees.filter(e=>(filter.value==='all'||e.active===(filter.value==='active'))&&e.name.toLowerCase().includes(search.value.toLowerCase())))
const total = id => store.analytics?.byEmployee.find(p=>p.employeeId===id&&p.currency===store.currency)?.total || 0
const selectedPayments = computed(()=>store.sortedPayments.filter(p=>p.employeeId===selected.value?.id))
function edit(e) { error.value=''; editing.value = e ? { ...e } : { name:'', role:'Официант', active:true } }
async function save() { busy.value=true; error.value=''; const isNew=!editing.value.id; try { const employee=await api.saveEmployee(editing.value); await store.load(); editing.value=null; if(isNew)await openAccess(employee); store.notify(isNew?'Сотрудник добавлен. Передайте ему приглашение.':'Изменения в команде сохранены') } catch(e) { error.value=e.message } finally { busy.value=false } }
const accessUrl = computed(() => access.value ? new URL(`/register?role=employee&invite=${access.value.accessToken}`,window.location.origin).href : '')
async function openAccess(employee) { accessError.value=''; try { if(employee.accessToken)access.value=employee;else{access.value=await api.inviteEmployee(employee.id);await store.load()} } catch(e) { store.notify(e.message) } }
async function copyAccess(type='link') { try { await navigator.clipboard.writeText(type==='code'?access.value.accessToken:accessUrl.value); store.notify(type==='code'?'Код приглашения скопирован':'Ссылка приглашения скопирована') } catch { accessError.value='Выделите код или ссылку и скопируйте вручную.' } }
</script>
<template><div class="page-heading"><div><h1>{{ $t('Команда') }}<span class="heading-dot">.</span></h1><p>{{ $t('Сотрудники ресторана, аккаунты и полученные чаевые.') }}</p></div><button class="btn btn-primary" @click="edit()"><Plus :size="18" />{{ $t('Добавить сотрудника') }}</button></div><div class="info-banner"><Link2 :size="18"/><span><strong>{{ $t('Как сотруднику получить аккаунт?') }}</strong> {{ $t('Добавьте его в команду, затем нажмите «Приглашение сотрудника» на карточке. Передайте код или ссылку — они нужны в форме регистрации с ролью «Сотрудник».') }}</span></div><div class="toolbar"><div class="tabs"><button :class="{active:filter==='all'}" @click="filter='all'">{{ $t('Все') }} <span>{{ store.employees.length }}</span></button><button :class="{active:filter==='active'}" @click="filter='active'">{{ $t('Активные') }}</button><button :class="{active:filter==='inactive'}" @click="filter='inactive'">{{ $t('Неактивные') }}</button></div><label class="search-input"><Search :size="18"/><input v-model="search" :placeholder="$t('Найти сотрудника')" :aria-label="$t('Поиск сотрудника')"></label></div><div v-if="!list.length" class="panel empty"><UsersRound :size="36"/><h3>{{ store.employees.length ? $t('Никого не нашли') : $t('В команде пока никого нет') }}</h3><p>{{ store.employees.length ? $t('Попробуйте изменить поиск или фильтр.') : $t('Добавьте сотрудника и пригласите его зарегистрировать личный аккаунт.') }}</p><button class="btn btn-primary" @click="edit()">{{ $t('Добавить сотрудника') }}</button></div><div class="employee-grid"><article v-for="e in list" :key="e.id" class="panel employee-card"><div class="employee-card-top"><span class="avatar large" :class="e.color">{{ initials(e.name) }}</span><button class="icon-btn" @click="edit(e)" :aria-label="$t('Редактировать {0}', {0: e.name})"><Pencil :size="17"/></button></div><h2>{{ e.name }}</h2><p class="muted">{{ $t(e.role) }}</p><span class="status" :class="e.active?'success':'cancelled'"><i></i>{{ e.active?$t('Активен'):$t('Неактивен') }}</span><span v-if="e.registered" class="account-connected">{{ $t('Аккаунт подключён') }}</span><GoalProgress :goal="e.goal"/><p v-if="!e.goal" class="employee-no-dream">{{ $t('Цель пока не указана') }}</p><div class="employee-sum"><div><span>{{ $t('Чаевые за всё время') }}</span><strong>{{ money(total(e.id)) }}</strong></div><Wallet :size="22"/></div><button class="text-link" @click="selected=e">{{ $t('Статистика сотрудника') }}<ArrowUpRight :size="17"/></button><button v-if="e.active && !e.registered" class="text-link employee-access" @click="openAccess(e)"><Link2 :size="15"/>{{ $t('Приглашение сотрудника') }}</button></article></div><BaseModal v-if="editing" :title="editing.id?$t('Редактировать сотрудника'):$t('Новый сотрудник')" :subtitle="$t('После добавления отправьте сотруднику приглашение.')" @close="!busy && (editing=null)"><form @submit.prevent="save" class="form-stack"><label>{{ $t('Имя и фамилия') }}<input v-model="editing.name" required minlength="2" maxlength="80" :placeholder="$t('Например, Анна Смирнова')"></label><label>{{ $t('Должность') }}<input v-model="editing.role" required maxlength="60" :placeholder="$t('Официант')"></label><label v-if="editing.id" class="checkbox-label"><input type="checkbox" v-model="editing.active">{{ $t('Принимает чаевые') }}<span class="muted">{{ $t('Неактивный сотрудник скрыт от гостей и не принимает чаевые. История сохранится.') }}</span></label><p v-if="error" class="error-text" role="alert">{{ $t(error) }}</p><button class="btn btn-primary" :disabled="busy">{{ busy?$t('Сохраняем…'):$t('Сохранить сотрудника') }}</button></form></BaseModal><BaseModal v-if="selected" :title="selected.name" :subtitle="$t(selected.role)" @close="selected=null"><GoalProgress :goal="selected.goal"/><div class="employee-detail"><span>{{ $t('Успешные чаевые') }}</span><strong>{{ money(total(selected.id)) }}</strong><span>{{ selectedPayments.filter(p=>p.status==='success').length }} {{ $t('успешных платежей') }}</span></div><PaymentTable :payments="selectedPayments.slice(0,10)" :employee-name="store.employeeName" /></BaseModal><BaseModal v-if="access" :title="$t('Приглашение сотрудника')" :subtitle="access.name" @close="access=null"><div class="form-stack"><p class="muted small-text">{{ $t('Отправьте ссылку сотруднику. Он создаст аккаунт с собственным email и паролем и получит доступ только к своим чаевым и целям. Приглашение можно использовать один раз.') }}</p><label>{{ $t('Код приглашения') }}<input :value="access.accessToken" readonly class="invitation-code"></label><button class="btn btn-primary" @click="copyAccess('code')"><Copy :size="17"/>{{ $t('Скопировать код') }}</button><label>{{ $t('Или передайте готовую ссылку') }}<input :value="accessUrl" readonly></label><p v-if="accessError" class="error-text">{{ $t(accessError) }}</p><button class="btn btn-outline" @click="copyAccess('link')"><Copy :size="17"/>{{ $t('Скопировать ссылку') }}</button><a :href="accessUrl" target="_blank" rel="noopener" class="btn btn-outline">{{ $t('Открыть регистрацию') }}<ArrowUpRight :size="17"/></a></div></BaseModal></template>
